style.css:
/* ===========================================
   Aero Frutiger GX - Base v1.0
   Compatible con Stylisher
=========================================== */

/* ---------- Variables ---------- */

:root{
    --af-accent:#79d8ff;
    --af-accent2:#9ef7d7;
    --af-white:#ffffff;
    --af-shadow:rgba(80,190,255,.35);
}

/* ---------- Transiciones ---------- */

*{
    transition:
        background-color .18s ease,
        border-color .18s ease,
        box-shadow .18s ease,
        color .18s ease !important;
}

/* ---------- Botones ---------- */

button,
input[type="button"],
input[type="submit"],
[role="button"]{

    border-radius:14px !important;

    border:1px solid rgba(255,255,255,.55) !important;

    box-shadow:
        inset 0 1px rgba(255,255,255,.85),
        0 0 8px rgba(120,220,255,.18) !important;
}

/* Hover */

button:hover,
input[type="button"]:hover,
input[type="submit"]:hover,
[role="button"]:hover{

    box-shadow:
        inset 0 1px rgba(255,255,255,.95),
        0 0 14px rgba(120,220,255,.35) !important;
}

/* ---------- Inputs ---------- */

input,
textarea,
select{

    border-radius:12px !important;

    border:1px solid rgba(180,235,255,.55) !important;

    box-shadow:
        inset 0 1px rgba(255,255,255,.6) !important;
}

/* ---------- Links ---------- */

a{

    color:#47bfff !important;

    text-decoration:none !important;
}

a:hover{

    text-shadow:
        0 0 5px rgba(120,220,255,.6);

}

/* ---------- Texto ---------- */

h1,h2,h3,h4,h5,h6{

    text-shadow:
        0 0 2px rgba(255,255,255,.9),
        0 0 8px rgba(120,220,255,.25);

}

/* ---------- Selección ---------- */

::selection{

    background:#8ee7ff !important;

    color:#00334d !important;

}

/* ---------- Scrollbars ---------- */

::-webkit-scrollbar{

    width:12px;

    height:12px;

}

::-webkit-scrollbar-track{

    background:rgba(220,245,255,.55);

    border-radius:999px;

}

::-webkit-scrollbar-thumb{

    background:linear-gradient(
        #b7f2ff,
        #7ddcff
    );

    border-radius:999px;

    border:2px solid rgba(255,255,255,.7);

}

::-webkit-scrollbar-thumb:hover{

    background:linear-gradient(
        #d2f8ff,
        #8ee7ff
    );

}
